{"implementation": "def solve(case):
    # Validate case structure
    if not isinstance(case, dict):
        raise ValueError("Case must be a dict")
    if 'threshold' not in case or 'calls' not in case:
        raise ValueError("Missing required keys: threshold, calls")
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    if len(calls) == 0:
        raise ValueError("calls list is empty")
    # Validate each call and compute diagnostics
    diagnostics = []
    accepted_ids = []
    for i, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f"Call at index {i} is not a dict")
        required = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
        for key in required:
            if key not in call:
                raise ValueError(f"Call at index {i} missing key: {key}")
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        pred_tokens = call['prediction_tokens']
        parseable = call['parseable']
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError(f"Call {call_id}: loss values must be numeric")
        if not isinstance(pred_tokens, int) or pred_tokens < 0:
            raise ValueError(f"Call {call_id}: prediction_tokens must be non-negative integer")
        if not isinstance(parseable, bool):
            raise ValueError(f"Call {call_id}: parseable must be boolean")
        gain = loss_without - loss_with
        # Normalize by at least one prediction token (use max to avoid division by zero)
        normalized_gain = gain / max(pred_tokens, 1)
        # Round to 4 decimal places
        rounded_gain = round(normalized_gain, 4)
        accepted = parseable and normalized_gain >= threshold
        if accepted:
            accepted_ids.append(call_id)
        diagnostics.append({
            'call_id': call_id,
            'normalized_gain': rounded_gain,
            'accepted': accepted
        })
    return {
        'accepted_call_ids': accepted_ids,
        'diagnostics': diagnostics
    }
